        text: "Don't just look at a placement percentage on a website — ask for actual student names, companies, and roles, and see if they're willing to share it (we publish ours, including real names like Sanjana Sunil at Accenture and Sanjay Suresh at IBM Bangalore). If an institute is vague about specifics, that's worth noting.",
